update ord_dis_delivery set
delivery_status_code = #{deliveryStatusCodeUpdate},
    distribution_quantity=#{distributionQuantity},
    distribution_amount= #{distributionAmount}
where
    delivery_status_code = #{deliveryStatusCode}
    AND distribution_type = #{distributionType}
    AND id = #{deliveryOrderId}

