select r.order_cycle_id,r.store_code,r.truncation_date_time,d.id as deliveryOrderId,d.delivery_order_no,d.delivery_status_code,d.distribution_amount from ord_dis_delivery d INNER JOIN ord_dis_deliv_request_delivery drd on drd.delivery_order_id = d.id INNER JOIN ord_dis_deliv_request r on r.id = drd.request_order_id where d.freeze_status = 'unFreeze' and d.id in
#{item.id}
and d.distribution_amount > 0 and d.biz_org_code = #{bizOrgCode}

select f.id as firstOrderId,f.first_order_no,f.store_code,d.id as deliveryOrderId,d.delivery_order_no,d.delivery_status_code,d.distribution_amount from ord_dis_delivery d INNER JOIN ord_dis_order_first_delivery fd on fd.delivery_order_id = d.id INNER JOIN ord_dis_order_first f on f.id = fd.first_order_id where d.freeze_status = 'unFreeze' and d.id in
#{item.id}
and f.first_order_status = 'executed' and d.biz_org_code = #{bizOrgCode} and f.is_delete = 0

